def build_wire(p, selected, private, trusted_out):
    from_uri = RESERVED if private else selected
    out = [
        "%s %s SIP/2.0" % (p.method, p.req_uri),
        "From: <%s>%s" % (from_uri, ";tag=" + p.from_tag if p.from_tag else ""),
        "To: <%s>%s" % (p.to_norm, ";tag=" + p.to_tag if p.to_tag else ""),
        "Call-ID: " + p.call_id,
        "CSeq: %d %s" % (p.cseq_num, p.method),
        "Privacy: " + ("id" if private else "none"),
    ]
    if (not private) or trusted_out:
        out.append("P-Asserted-Identity: <%s>" % selected)
    if p.ctype is not None:
        out.append("Content-Type: " + p.ctype)
    out.append("Content-Length: %d" % len(p.body))
    return "\r\n".join(out) + "\r\n\r\n" + p.body


# ---------------------------------------------------------------------------
# batch driver
# ---------------------------------------------------------------------------

def process(batch):
    alias = {}
    for ident, alist in batch["directory"].items():
        if ident != RESERVED:
            alias[ident] = ident
        for a in alist:
            if a != RESERVED:
                alias[a] = ident

    accounts = {}
    for subject, acct in batch["accounts"].items():
        allowed = set(acct["allow"])
        allowed.add(acct["primary"])
        accounts[subject] = (acct["primary"], allowed)

    gateways = {}
    for gname, gw in batch["gateways"].items():
        peers = dict((n, set(d)) for n, d in gw["peers"].items())
        gateways[gname] = (set(gw["local_domains"]), peers)

    results = []
    for job in batch["jobs"]:
        try:
            if "source" in job:
                src = results[job["source"]]
                if src["status"] != "accept":
                    raise UpstreamErr()
                text = src["wire"]
            else:
                text = job["raw"]
            p = parse_request(text)
            gw_tables = gateways[job["gateway"]]
            basis, selected = select_identity(
                p, job["ingress"], gw_tables, alias, accounts)
            private = p.from_anon or p.privacy_id
            wire = build_wire(p, selected, private, job["trusted_out"])
            results.append({
                "status": "accept",
                "identity": selected,
                "basis": basis,
                "private": private,
                "wire": wire,
            })
        except UpstreamErr:
            results.append({"status": "reject", "reason": "upstream"})
        except SyntaxErr:
            results.append({"status": "reject", "reason": "syntax"})
        except UnauthErr:
            results.append({"status": "reject", "reason": "unauthenticated"})
        except IdentErr:
            results.append({"status": "reject", "reason": "identity"})
    return {"results": results}


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------

def _pairs(items):
    d = {}
    for k, v in items:
        if k in d:
            raise ValueError("duplicate key")
        d[k] = v
    return d


def _constant(name):
    raise ValueError("nonfinite number")


def main():
    data = sys.stdin.buffer.read()
    try:
        batch = json.loads(
            data.decode("utf-8"),
            object_pairs_hook=_pairs,
            parse_constant=_constant,
        )
    except Exception:
        sys.exit(1)
    out = process(batch)
    sys.stdout.buffer.write(json.dumps(out).encode("utf-8"))
    sys.stdout.buffer.write(b"\n")


if __name__ == "__main__":
    main()
